import asyncio


async def crawl(start, get_links, limit=3):
    gate = asyncio.Semaphore(limit)
    distance = {start: 0}

    async def links_of(url):
        async with gate:
            try:
                return await get_links(url)
            except Exception:
                return []

    level = [start]
    depth = 0
    while level:
        found = await asyncio.gather(*(links_of(url) for url in level))
        depth += 1
        next_level = []
        for links in found:
            for link in links:
                if link not in distance:
                    distance[link] = depth
                    next_level.append(link)
        level = next_level
    return distance
